fn fenced_blocks<'a>(markdown: &'a str, language: &str) -> Vec<&'a str> {
    let opening = format!("```{language}\n");
    markdown
        .split(&opening)
        .skip(1)
        .map(|tail| {
            tail.split_once("\n```")
                .map(|(block, _)| block)
                .unwrap_or_else(|| panic!("unterminated {language} block"))
        })
        .collect()
}

